//! JLV types and assignability (JDD 0004, "Values and type system").
//!
//! `Plain(T)` holds for the scalar types and `Value`, and for `List<T>` or `Map<T>`
//! exactly when it holds for `T`; it never holds for a nominal type. Assignability
//! `A <= B` is the least relation generated by
//!
//! ```text
//! T <= T,    Plain(T) / T <= Value,    A <= B / List<A> <= List<B>,    A <= B / Map<A> <= Map<B>
//! ```
//!
//! together with `Never <= T` for the result of `fail`. The relation is transitive by
//! induction on the derivation, so [`assignable`] needs no closure step.

use crate::Value;
use std::fmt;
use std::sync::Arc;

/// Checks a boundary value against a closed type. Nominals check their type identity;
/// their versioned payload contracts remain the owning library's responsibility.
pub fn contains_value(ty: &Type, value: &Value) -> bool {
    match ty {
        Type::Null => matches!(value, Value::Null),
        Type::Bool => matches!(value, Value::Bool(_)),
        Type::Int => matches!(value, Value::Int(_)),
        Type::Text => matches!(value, Value::Text(_)),
        Type::Bytes => matches!(value, Value::Bytes(_)),
        Type::Value => value.is_plain(),
        Type::List(item) => {
            value.as_list().is_some_and(|v| v.iter().all(|v| contains_value(item, v)))
        }
        Type::Map(item) => {
            value.as_map().is_some_and(|v| v.values().all(|v| contains_value(item, v)))
        }
        Type::Nominal(id, _) => value.as_opaque(id).is_some(),
        Type::Record(record) => value.as_map().is_some_and(|map| {
            record.fields.iter().all(|field| match map.get(&field.name) {
                Some(value) => contains_value(&field.ty, value),
                None => !field.required,
            }) && map.iter().all(|(key, value)| {
                record.field(key).is_some()
                    || record.rest.as_ref().is_some_and(|ty| contains_value(ty, value))
            })
        }),
        Type::Never | Type::Var(_) | Type::Keyed(_) => false,
    }
}

/// A JLV type.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Type {
    /// The type of `null`.
    Null,
    /// Booleans.
    Bool,
    /// Checked signed 64-bit integers.
    Int,
    /// UTF-8 texts.
    Text,
    /// Byte strings.
    Bytes,
    /// The recursive plain-data union; never an unchecked `Any`.
    Value,
    /// An immutable list.
    List(Box<Type>),
    /// An immutable map with text keys.
    Map(Box<Type>),
    /// A library type such as `ResourceRef` or `SecretRef<Text>`.
    Nominal(Arc<str>, Vec<Type>),
    /// A record shape a library interface expects, such as an instance's `limits`.
    Record(Arc<RecordType>),
    /// The type of an expression that never produces a value, such as `fail(...)`.
    Never,
    /// A type variable of a library signature; never the type of a source expression.
    Var(u8),
    /// A library result whose type comes from a captured schema, looked up by the call's
    /// literal key: `ctx.input("name")` has the type the input schema gives `name`.
    Keyed(Arc<str>),
}

/// A closed record shape with required and optional fields.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct RecordType {
    /// The fields, sorted by name.
    pub fields: Vec<FieldType>,
    /// The type of fields not listed, for an open record such as labels; `None` closes it.
    pub rest: Option<Type>,
}

/// One field of a record shape.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct FieldType {
    /// The field name.
    pub name: Arc<str>,
    /// Its type.
    pub ty: Type,
    /// Whether a record must give it.
    pub required: bool,
}

impl RecordType {
    /// The field named `name`.
    pub fn field(&self, name: &str) -> Option<&FieldType> {
        self.fields.iter().find(|f| &*f.name == name)
    }
}

impl Type {
    /// `List<item>`.
    pub fn list(item: Type) -> Type {
        Type::List(Box::new(item))
    }

    /// `Map<item>`.
    pub fn map(item: Type) -> Type {
        Type::Map(Box::new(item))
    }

    /// A nominal type without arguments.
    pub fn nominal(name: &str) -> Type {
        Type::Nominal(Arc::from(name), Vec::new())
    }

    /// How deeply the type nests: 0 for a type without parts, and one more than its
    /// deepest part otherwise. The checker refuses types deeper than `[limits]
    /// type_depth` where it forms them, so this recursion is bounded (JDD 0013).
    pub fn depth(&self) -> usize {
        let deepest = |types: &mut dyn Iterator<Item = &Type>| types.map(Type::depth).max();
        match self {
            Type::List(item) | Type::Map(item) => 1 + item.depth(),
            Type::Nominal(_, args) => deepest(&mut args.iter()).map_or(0, |d| d + 1),
            Type::Record(shape) => {
                let mut parts = shape.fields.iter().map(|f| &f.ty).chain(shape.rest.as_ref());
                1 + deepest(&mut parts).unwrap_or(0)
            }
            _ => 0,
        }
    }

    /// Whether this is the nominal type `name`.
    pub fn is_nominal(&self, name: &str) -> bool {
        matches!(self, Type::Nominal(n, _) if &**n == name)
    }

    /// The core type with this name and arguments, if there is one.
    pub fn core(name: &str, args: &[Type]) -> Option<Type> {
        let ty = match (name, args) {
            ("Null", []) => Type::Null,
            ("Bool", []) => Type::Bool,
            ("Int", []) => Type::Int,
            ("Text", []) => Type::Text,
            ("Bytes", []) => Type::Bytes,
            ("Value", []) => Type::Value,
            ("List", [item]) => Type::list(item.clone()),
            ("Map", [item]) => Type::map(item.clone()),
            _ => return None,
        };
        Some(ty)
    }

    /// Reads a type written as text, such as `Map<List<SecretRef<Text>>>`; a name that
    /// is not a core type is nominal. Descriptors and schemas use this spelling. `None`
    /// when the text is no type or nests deeper than the default `type_depth`.
    pub fn parse(text: &str) -> Option<Type> {
        let (ty, rest) = parse_prefix(text.trim(), jlv_core::Limits::default().type_depth + 1)?;
        rest.trim().is_empty().then_some(ty)
    }

    /// Whether a value of this type is ordinary data that may become `Value`.
    pub fn is_plain(&self) -> bool {
        match self {
            Type::Null | Type::Bool | Type::Int | Type::Text | Type::Bytes | Type::Value => true,
            Type::List(item) | Type::Map(item) => item.is_plain(),
            Type::Never => true,
            // A record shape belongs to a library interface; it is not plain data even
            // when its fields are (JDD 0004).
            Type::Record(_) | Type::Nominal(..) | Type::Var(_) | Type::Keyed(_) => false,
        }
    }

    /// Whether the type contains a signature variable or keyed placeholder.
    pub fn is_open(&self) -> bool {
        match self {
            Type::Var(_) | Type::Keyed(_) => true,
            Type::List(item) | Type::Map(item) => item.is_open(),
            Type::Nominal(_, args) => args.iter().any(Type::is_open),
            _ => false,
        }
    }
}

/// Reads one type from the start of `text`, nested at most `room` levels more, and
/// returns it with the rest. A descriptor's type is text from a plugin, so its nesting
/// is refused beyond `type_depth`, which also bounds this recursion (JDD 0013).
fn parse_prefix(text: &str, room: usize) -> Option<(Type, &str)> {
    let room = room.checked_sub(1)?;
    let end = text
        .find(|c: char| !(c.is_ascii_alphanumeric() || c == '_' || c == '.'))
        .unwrap_or(text.len());
    let (name, mut rest) = text.split_at(end);
    if name.is_empty() {
        return None;
    }
    let mut args = Vec::new();
    if let Some(inner) = rest.trim_start().strip_prefix('<') {
        rest = inner;
        loop {
            let (arg, after) = parse_prefix(rest.trim_start(), room)?;
            args.push(arg);
            let after = after.trim_start();
            if let Some(next) = after.strip_prefix(',') {
                rest = next;
            } else {
                rest = after.strip_prefix('>')?;
                break;
            }
        }
    }
    let core = ["Null", "Bool", "Int", "Text", "Bytes", "Value", "List", "Map"].contains(&name);
    let ty = match Type::core(name, &args) {
        Some(ty) => ty,
        None if core => return None,
        None => Type::Nominal(Arc::from(name), args),
    };
    Some((ty, rest))
}

/// Whether a value of type `from` may be used where `to` is expected.
pub fn assignable(from: &Type, to: &Type) -> bool {
    if from == to || *from == Type::Never {
        return true;
    }
    match (from, to) {
        (_, Type::Value) => from.is_plain(),
        (Type::List(a), Type::List(b)) | (Type::Map(a), Type::Map(b)) => assignable(a, b),
        _ => false,
    }
}

/// The one type of a collection literal's elements: the element type to which every
/// other element is assignable. `None` means the elements have no common type without
/// an explicit `List<Value>` or `Map<Value>` (JDD 0004).
pub fn common_type<'a>(types: impl Iterator<Item = &'a Type> + Clone) -> Option<Type> {
    let mut candidate: Option<&'a Type> = None;
    for ty in types.clone() {
        if *ty == Type::Never {
            continue;
        }
        match candidate {
            None => candidate = Some(ty),
            Some(current) if assignable(current, ty) && !assignable(ty, current) => {
                candidate = Some(ty);
            }
            Some(_) => {}
        }
    }
    if let Some(best) = candidate {
        return types.clone().all(|t| assignable(t, best)).then(|| best.clone());
    }
    types.clone().next().filter(|t| **t == Type::Never).cloned()
}

impl fmt::Display for Type {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Type::Null => f.write_str("Null"),
            Type::Bool => f.write_str("Bool"),
            Type::Int => f.write_str("Int"),
            Type::Text => f.write_str("Text"),
            Type::Bytes => f.write_str("Bytes"),
            Type::Value => f.write_str("Value"),
            Type::List(item) => write!(f, "List<{item}>"),
            Type::Map(item) => write!(f, "Map<{item}>"),
            Type::Nominal(name, args) if args.is_empty() => f.write_str(name),
            Type::Nominal(name, args) => {
                let args: Vec<String> = args.iter().map(Type::to_string).collect();
                write!(f, "{name}<{}>", args.join(", "))
            }
            Type::Record(record) => write_record(f, record),
            Type::Never => f.write_str("Never"),
            Type::Var(n) => write!(f, "T{n}"),
            Type::Keyed(table) => write!(f, "<{table} entry>"),
        }
    }
}

fn write_record(f: &mut fmt::Formatter<'_>, record: &RecordType) -> fmt::Result {
    f.write_str("{ ")?;
    for (i, field) in record.fields.iter().enumerate() {
        if i > 0 {
            f.write_str(", ")?;
        }
        let mark = if field.required { "" } else { "?" };
        write!(f, "{}{mark}: {}", field.name, field.ty)?;
    }
    if let Some(rest) = &record.rest {
        let comma = if record.fields.is_empty() { "" } else { ", " };
        write!(f, "{comma}..: {rest}")?;
    }
    f.write_str(" }")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn secret() -> Type {
        Type::Nominal(Arc::from("SecretRef"), vec![Type::Text])
    }

    #[test]
    fn covariance_never_reaches_a_nominal_element() {
        let resource = Type::nominal("ResourceRef");
        assert!(assignable(
            &Type::list(Type::list(Type::Int)),
            &Type::list(Type::list(Type::Value))
        ));
        assert!(!assignable(&Type::list(resource.clone()), &Type::list(Type::Value)));
        assert!(!assignable(&Type::map(Type::list(secret())), &Type::Value));
        assert!(assignable(&Type::list(resource.clone()), &Type::list(resource)));
        assert!(!assignable(&Type::Value, &Type::Int));
    }

    #[test]
    fn literals_need_one_element_type() {
        let ints = [Type::Int, Type::Never, Type::Int];
        assert_eq!(common_type(ints.iter()), Some(Type::Int));
        let mixed = [Type::Int, Type::Bool];
        assert_eq!(common_type(mixed.iter()), None);
        let widening = [Type::Int, Type::Value];
        assert_eq!(common_type(widening.iter()), Some(Type::Value));
    }

    #[test]
    fn types_parse_from_their_spelling() {
        for text in ["Int", "List<Map<Value>>", "SecretRef<Text>", "Map<List<SecretRef<Text>>>"] {
            assert_eq!(Type::parse(text).unwrap().to_string(), text);
        }
        assert_eq!(Type::parse("List<Int"), None);
        assert_eq!(Type::parse("List"), None);
        assert_eq!(Type::parse(""), None);
        // JDD 0013: a descriptor's type nests no deeper than `type_depth`, so a hostile
        // one is refused rather than recursing once per `<`.
        let nested = |n: usize| format!("{}Int{}", "List<".repeat(n), ">".repeat(n));
        assert!(Type::parse(&nested(64)).is_some());
        assert_eq!(Type::parse(&nested(65)), None);
        let hostile = nested(100_000);
        let refused = std::thread::Builder::new()
            .stack_size(256 << 10)
            .spawn(move || Type::parse(&hostile).is_none())
            .unwrap()
            .join()
            .unwrap();
        assert!(refused);
    }

    #[test]
    fn types_print_as_source_spells_them() {
        assert_eq!(Type::map(Type::list(secret())).to_string(), "Map<List<SecretRef<Text>>>");
    }
}
